(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18+Math.sin(x*0.015+t*0.3)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.15)*8+Math.cos(sy*0.03+t*0.2)*6;
  const w2y = Math.cos(sy*0.022+t*0.18)*8+Math.sin(sx*0.028-t*0.25)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [120+Math.sin(t*0.4)*90, 70+Math.cos(t*0.35)*45, 0.09, 2.1, 0],
    [360+Math.cos(t*0.45)*80, 80+Math.sin(t*0.5)*55, 0.08, 1.8, 1],
    [240+Math.sin(t*0.3+2)*130, 40+Math.cos(t*0.45+1)*35, 0.07, 2.4, 2],
    [80+Math.cos(t*0.55+1)*70, 170+Math.sin(t*0.4+3)*50, 0.11, 1.6, 3],
    [400+Math.sin(t*0.38+4)*85, 160+Math.cos(t*0.6+2)*65, 0.065, 2.7, 4],
    [200+Math.cos(t*0.33+5)*110, 210+Math.sin(t*0.5)*70, 0.085, 2.0, 5],
    [320+Math.sin(t*0.42+3)*75, 120+Math.cos(t*0.48+4)*80, 0.075, 2.2, 6],
    [160+Math.cos(t*0.37+6)*95, 140+Math.sin(t*0.43+2)*60, 0.1, 1.9, 7]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const[sX,sY,f,sp,p] of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const ph=p*Math.PI*0.25;
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    aS2+=Math.cos(d*f*1.3-t*sp*0.8+ph*0.7);
    iS2+=Math.cos(d*f*0.5+t*sp*0.4-ph*0.5);
  }
  const act=(aS+aS2*0.5)/12, inh=(iS+iS2*0.5)/12;
  const bg1=Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*1.0);
  const bg2=Math.sin((fx+fy)*0.1+t*2.2)*0.3+Math.sin((fx-fy)*0.085-t*1.8)*0.3;
  const bg3=Math.sin(fx*0.06+Math.sin(fy*0.04+t*0.5)*2+t*1.3);
  const bg=(bg1+bg2+bg3)/2.6;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3=Math.sin(dist*0.06-ang*2-t*1.8+Math.sin(ang*2+dist*0.02-t)*1.5);
  const spiral=(sp1+sp2+sp3)*0.25;
  const cx2=160+Math.sin(t*0.2)*60, cy2=100+Math.cos(t*0.25)*40;
  const dist2=Math.sqrt((fx-cx2)**2+(fy-cy2)**2), ang2=Math.atan2(fy-cy2,fx-cx2);
  const sp4=Math.sin(dist2*0.055-ang2*3-t*1.6)*0.3;
  const moire=Math.sin(dist*0.12)*Math.sin(dist2*0.12)*2;
  const cell1=Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.095+t)*0.5;
  const cell2=Math.sin(fx*0.1-t*0.3)*Math.cos(fy*0.12+t*0.2)+Math.sin((fx-fy)*0.07-t*0.4)*0.4;
  const cell=(Math.tanh(cell1*1.4)+Math.tanh(cell2*1.2))*0.15;
  const feed=Math.tanh((act-inh*0.65+bg*0.35+spiral+sp4+moire*0.15)*2.0);
  const diff=Math.tanh((inh-act*0.5-bg*0.2)*1.8);
  const cascade=Math.tanh((feed*0.6+diff*0.4+cell)*1.5);
  const reaction=Math.tanh((feed*0.55+cascade*0.35+diff*0.1)*2.5);
  const v=reaction*0.5+0.5;
  const pal=[
    [6,12,52],[12,42,88],[18,82,115],[24,128,132],
    [140,175,95],[215,195,60],[225,135,65],[185,65,72],
    [120,35,82],[55,18,68],[20,10,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const pulse=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.4?1.04:0.96;
  const shimmer=Math.sin(fx*0.3+fy*0.2+t*4)*0.03*edge;
  const L=pulse*edge+shimmer;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*L))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*L))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*L))|0
  ];
}
